<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\MediaAsset; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class MediaAssetController extends Controller { public function index(){return view('admin.media.index',['items'=>MediaAsset::latest()->paginate(24)]);} public function store(Request $r){$d=$r->validate(['title'=>'required|string|max:190','type'=>'required|in:image,audio,video,document','alt_text'=>'nullable|string|max:255','file'=>'required|file|max:51200','is_published'=>'sometimes|boolean']);$path=$r->file('file')->store('media','public');MediaAsset::create(['title'=>$d['title'],'type'=>$d['type'],'alt_text'=>$d['alt_text']??null,'file_path'=>$path,'mime_type'=>$r->file('file')->getMimeType(),'file_size'=>$r->file('file')->getSize(),'is_published'=>$r->boolean('is_published')]);return back()->with('success','Media uploaded.');} public function destroy(MediaAsset $media){if($media->file_path)Storage::disk('public')->delete($media->file_path);$media->delete();return back()->with('success','Media deleted.');} }
